mapper.select:
SELECT ida.id, ida.apply_no, ida.outbound_no, ida.operation_no, ida.receive_unit, ida.receive_unit_name, ida.receive_duty_dept, ida.receive_duty_dept_name, ida.receive_duty_group, ida.receive_duty_group_name, ida.receive_duty_person, ida.device_category, ida.device_type, ida.receive_duty_person, ida.receive_duty_person_name, ida.`status`, ida.apply_num, ida.old_to_new, ida.operation, ida.apply_date, ida.process_status, ida.device_category_name, ida.device_type_name FROM idevelop_device_apply ida
ida.is_deleted = 0
AND ida.apply_no LIKE CONCAT('%', #{deviceApplyDTO.applyNo}, '%')
AND ida.outbound_no LIKE CONCAT('%', #{deviceApplyDTO.outboundNo}, '%')
AND ida.operation_no LIKE CONCAT('%', #{deviceApplyDTO.operationNo}, '%')
AND ida.apply_user_name LIKE CONCAT('%', #{deviceApplyDTO.applyUser}, '%')
AND ida.device_category = #{deviceApplyDTO.deviceCategory}
AND ida.device_type = #{deviceApplyDTO.deviceType}
AND ida.old_to_new = #{deviceApplyDTO.oldToNew}
AND ida.receive_unit_name = #{deviceApplyDTO.receiveUnitName}
AND ida.receive_duty_dept = #{deviceApplyDTO.receiveDutyDept}
AND ida.status = #{deviceApplyDTO.status}
AND ida.region_code LIKE CONCAT ( #{deviceApplyDTO.regionCode}, '%')
ORDER BY ida.create_time DESC
